// Parse Gemini response + inject UAE Amazon affiliate links
const response = $input.item.json;
const selectedProduct = $('🎯 Select UAE Topic & Product').item.json.selected_product;

let text = response?.candidates?.[0]?.content?.parts?.[0]?.text || '';
text = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

let article;
try {
  article = JSON.parse(text);
} catch(e) {
  const match = text.match(/\{[\s\S]*\}/);
  if (match) article = JSON.parse(match[0]);
  else throw new Error('Parse failed: ' + text.slice(0, 200));
}

// UAE Amazon affiliate tag
const UAE_TAG = 'plantsmag-ae-21';
const UAE_BASE = 'https://www.amazon.ae/dp/';
const COM_BASE = 'https://www.amazon.com/dp/';

// Replace [AMAZON_UAE: name | ASIN] placeholders
let content = article.content;
content = content.replace(/\[AMAZON_UAE:\s*([^|]+)\|\s*([A-Z0-9]+)\]/gi, (match, name, asin) => {
  const uaeUrl = `${UAE_BASE}${asin.trim()}?tag=${UAE_TAG}`;
  const comUrl = `${COM_BASE}${asin.trim()}?tag=plantsmag-20`;
  return `<div class="pm-affiliate-box" style="background:linear-gradient(135deg,#fffbeb,#fef3c7);border-left:4px solid #d97706;padding:20px;margin:30px 0;border-radius:8px;">
  <p style="margin:0;"><strong>🛒 ${name.trim()}</strong></p>
  <p style="margin:8px 0;"><a href="${uaeUrl}" target="_blank" rel="nofollow noopener" style="background:#febd69;color:#111;padding:10px 20px;text-decoration:none;border-radius:5px;font-weight:bold;display:inline-block;margin-right:10px;">Buy on Amazon UAE 🇦🇪 →</a>
  <a href="${comUrl}" target="_blank" rel="nofollow noopener" style="color:#0066c0;font-weight:bold;">Also on Amazon US →</a></p>
</div>`;
});

// Add featured product CTA at end
const featuredUrl = `${UAE_BASE}${selectedProduct.asin}?tag=${UAE_TAG}`;
content += `
<div style="background:linear-gradient(135deg,#fff7ed,#ffedd5);border:2px solid #ea580c;padding:25px;margin:40px 0;border-radius:10px;text-align:center;">
  <h3 style="color:#9a3412;margin-top:0;">🌿 Our #1 Recommendation for UAE Plant Parents</h3>
  <p><strong>${selectedProduct.name}</strong> — the most effective solution for the challenges discussed in this article.</p>
  <a href="${featuredUrl}" target="_blank" rel="nofollow noopener" style="background:#ea580c;color:white;padding:14px 30px;text-decoration:none;border-radius:8px;font-weight:bold;font-size:16px;display:inline-block;">Check Price on Amazon UAE 🇦🇪</a>
</div>`;

return {
  title: article.title,
  slug: article.slug || article.title.toLowerCase().replace(/[^a-z0-9]+/g, '-').slice(0, 60),
  meta_description: article.meta_description || '',
  focus_keyword: article.focus_keyword || '',
  primary_asin: article.primary_asin || selectedProduct.asin,
  content: content,
  market: 'UAE'
};

